<?php
declare(strict_types=1);require_once '../config/config.php';require_once '../includes/church-book-functions.php';requireLogin();cb_require_permission('wedding_vows.view');$conn->set_charset('utf8mb4');$q=cb_clean($_GET['q']??'');$status=cb_clean($_GET['status']??'');$ceremony=cb_clean($_GET['ceremony']??'');$from=cb_clean($_GET['from']??'');$to=cb_clean($_GET['to']??'');$where=['1=1'];$types='';$params=[];
if($q!==''){$where[]="(groom_name LIKE ? OR bride_name LIKE ? OR register_no LIKE ? OR certificate_no LIKE ? OR officiant LIKE ? OR venue LIKE ?)";$like="%{$q}%";for($i=0;$i<6;$i++){$params[]=$like;$types.='s';}}if(in_array($status,['Scheduled','Banns','Solemnized','Postponed','Cancelled'],true)){$where[]='status=?';$params[]=$status;$types.='s';}if(in_array($ceremony,['Banns','Licence','Special Licence','Other'],true)){$where[]='ceremony_type=?';$params[]=$ceremony;$types.='s';}if($from!==''&&cb_valid_date($from)){$where[]='wedding_date>=?';$params[]=$from;$types.='s';}if($to!==''&&cb_valid_date($to)){$where[]='wedding_date<=?';$params[]=$to;$types.='s';}
$rows=cb_fetch_all($conn,"SELECT * FROM wedding_vows WHERE ".implode(' AND ',$where)." ORDER BY wedding_date DESC,id DESC",$types,$params);header('Content-Type:text/csv;charset=UTF-8');header('Content-Disposition:attachment;filename="wedding-vows-'.date('Y-m-d').'.csv"');$o=fopen('php://output','w');fprintf($o,chr(0xEF).chr(0xBB).chr(0xBF));fputcsv($o,['Register No','Wedding Date','Time','Venue','Status','Groom','Groom Phone','Groom Address','Bride','Bride Phone','Bride Address','Ceremony Basis','Banns 1','Banns 2','Banns 3','Licence No','Certificate No','Witness 1','Witness 2','Officiant','Assisting Minister','Scripture/Theme','Vows','Remarks']);foreach($rows as $r)fputcsv($o,[$r['register_no'],$r['wedding_date'],$r['wedding_time'],$r['venue'],$r['status'],$r['groom_name'],$r['groom_phone'],$r['groom_address'],$r['bride_name'],$r['bride_phone'],$r['bride_address'],$r['ceremony_type'],$r['banns_date_1'],$r['banns_date_2'],$r['banns_date_3'],$r['marriage_licence_no'],$r['certificate_no'],$r['witness_1'],$r['witness_2'],$r['officiant'],$r['assisting_minister'],$r['scripture_theme'],$r['vows_text'],$r['remarks']]);fclose($o);exit;
